from .errors import WSpawnError
from ._winapi import (
    FILE_TYPE_CHAR,
    FILE_TYPE_DISK,
    FILE_TYPE_PIPE,
    FILE_TYPE_UNKNOWN,
    file_type,
    get_console_mode,
)


def handle_kind(handle):
    """Return ``"file"``, ``"pipe"``, ``"console"`` or ``"unknown"``.

    Uses the Win32 ``GetFileType`` and ``GetConsoleMode`` APIs to classify
    the object.  Raises :class:`WSpawnError` for invalid handles or
    non-integer arguments.
    """
    try:
        number = int(handle)
    except (TypeError, ValueError):
        raise WSpawnError(
            "handle must be an integer, got %r" % (handle,), kind="badarg"
        )

    try:
        ft = file_type(number)
    except OSError as exc:
        winerr = getattr(exc, "winerror", None)
        # ERROR_INVALID_HANDLE = 6
        if winerr == 6:
            raise WSpawnError(
                "invalid handle: %r" % (handle,), kind="unsupported", handle=handle
            ) from exc
        raise WSpawnError(str(exc), kind="os", handle=handle) from exc

    if ft == FILE_TYPE_DISK:
        return "file"
    if ft == FILE_TYPE_PIPE:
        return "pipe"
    if ft == FILE_TYPE_CHAR:
        # CHAR covers consoles and serial ports etc. Try GetConsoleMode to
        # distinguish.
        try:
            get_console_mode(number)
            return "console"
        except OSError:
            # Not a console -- could be a serial port, printer, etc.
            return "unknown"
    # FILE_TYPE_UNKNOWN or FILE_TYPE_REMOTE
    return "unknown"

