import os
import subprocess
import sys

from .errors import WSpawnError
from ._winapi import (
    HANDLE_FLAG_INHERIT,
    create_process_with_handle_list,
    close_handle,
    get_handle_information,
    set_handle_information,
)


class SpawnedProcess(object):
    """A helper process started by :func:`spawn`."""

    def __init__(self, pid, process_handle, inherit):
        self._pid = pid
        self._process_handle = process_handle
        self.inherit = tuple(inherit)
        self.pid = pid
        self.returncode = None

    def wait(self, timeout=None):
        if self.returncode is not None:
            return self.returncode
        import ctypes
        from ctypes import wintypes

        k32 = ctypes.windll.kernel32
        INFINITE = 0xFFFFFFFF

        if timeout is None:
            ms = INFINITE
        else:
            ms = int(timeout * 1000)

        WAIT_OBJECT_0 = 0x00000000
        WAIT_TIMEOUT = 0x00000102

        result = k32.WaitForSingleObject(
            wintypes.HANDLE(self._process_handle), wintypes.DWORD(ms)
        )
        if result == WAIT_TIMEOUT:
            raise subprocess.TimeoutExpired(cmd=None, timeout=timeout)

        # Get exit code
        exit_code = wintypes.DWORD()
        ok = k32.GetExitCodeProcess(
            wintypes.HANDLE(self._process_handle), ctypes.byref(exit_code)
        )
        if ok:
            self.returncode = exit_code.value
        return self.returncode

    def poll(self):
        if self.returncode is not None:
            return self.returncode
        import ctypes
        from ctypes import wintypes

        k32 = ctypes.windll.kernel32
        exit_code = wintypes.DWORD()
        ok = k32.GetExitCodeProcess(
            wintypes.HANDLE(self._process_handle), ctypes.byref(exit_code)
        )
        if ok and exit_code.value != 259:  # STILL_ACTIVE = 259
            self.returncode = exit_code.value
        return self.returncode

    def terminate(self):
        import ctypes
        from ctypes import wintypes

        k32 = ctypes.windll.kernel32
        k32.TerminateProcess(wintypes.HANDLE(self._process_handle), 1)

    def __del__(self):
        try:
            if self._process_handle is not None:
                close_handle(self._process_handle)
                self._process_handle = None
        except Exception:
            pass


def _normalise_argv(argv):
    if isinstance(argv, (str, bytes)):
        raise WSpawnError(
            "argv must be a sequence of arguments, not a single string",
            kind="badarg",
        )
    try:
        items = [os.fspath(item) for item in argv]
    except TypeError as exc:
        raise WSpawnError(
            "argv must be an iterable of paths: %s" % exc, kind="badarg"
        ) from exc
    if not items:
        raise WSpawnError("argv must not be empty", kind="badarg")
    return items


def _normalise_handles(inherit):
    if inherit is None:
        return ()
    if isinstance(inherit, int):
        raise WSpawnError(
            "inherit must be a sequence of handles, not a single handle",
            kind="badarg",
        )
    try:
        return tuple(int(item) for item in inherit)
    except (TypeError, ValueError) as exc:
        raise WSpawnError(
            "inherit must contain integer handles: %s" % exc, kind="badarg"
        ) from exc


def _get_std_handle(fd_number):
    """Return the Windows HANDLE value for a standard stream (0, 1, 2)."""
    import ctypes
    from ctypes import wintypes

    STD_INPUT_HANDLE = -10
    STD_OUTPUT_HANDLE = -11
    STD_ERROR_HANDLE = -12

    mapping = {0: STD_INPUT_HANDLE, 1: STD_OUTPUT_HANDLE, 2: STD_ERROR_HANDLE}
    std_id = mapping.get(fd_number)
    if std_id is None:
        return None

    k32 = ctypes.windll.kernel32
    k32.GetStdHandle.restype = wintypes.HANDLE
    k32.GetStdHandle.argtypes = [wintypes.DWORD]
    h = k32.GetStdHandle(wintypes.DWORD(std_id))
    val = h.value if hasattr(h, 'value') else int(h)
    if val == 0 or val == -1:
        return None
    return val


def _handle_from_stream(stream):
    """Extract a Windows HANDLE integer from a Python file-like object.

    Supports:
    - int (already a handle)
    - Objects with .fileno() that returns a CRT fd -> convert to OS handle
    - Objects with .handle attribute (raw Windows handle)
    """
    if stream is None:
        return None
    if isinstance(stream, int):
        return stream

    # Try to get a file descriptor via fileno()
    try:
        fd = stream.fileno()
    except (AttributeError, OSError, ValueError):
        fd = None

    if fd is not None:
        # Convert CRT fd to Windows HANDLE
        import msvcrt
        return msvcrt.get_osfhandle(fd)

    # Try .handle attribute
    h = getattr(stream, 'handle', None)
    if h is not None:
        return int(h)

    raise WSpawnError(
        "cannot extract a Windows handle from %r" % (stream,),
        kind="badarg",
    )


def _build_command_line(argv):
    """Build a Windows command line string from an argument list.

    Uses proper quoting so that arguments with spaces are preserved.
    """
    import subprocess
    # subprocess.list2cmdline does exactly what we need for Windows
    return subprocess.list2cmdline(argv)


def spawn(argv, inherit=(), stdin=None, stdout=None, stderr=None):
    """Start a helper process, handing it the objects named in ``inherit``.

    Only the handles explicitly listed in *inherit* (plus any standard stream
    handles supplied via *stdin*/*stdout*/*stderr*) will be visible to the
    child process.  All other handles in the parent are excluded regardless
    of their inheritable flag.

    Returns a :class:`SpawnedProcess`.
    """
    command = _normalise_argv(argv)
    handles = _normalise_handles(inherit)

    # Resolve standard stream handles
    stdin_h = _handle_from_stream(stdin)
    stdout_h = _handle_from_stream(stdout)
    stderr_h = _handle_from_stream(stderr)

    # If no explicit std streams, use the current process's standard handles
    if stdin_h is None:
        stdin_h = _get_std_handle(0)
    if stdout_h is None:
        stdout_h = _get_std_handle(1)
    if stderr_h is None:
        stderr_h = _get_std_handle(2)

    # Build the complete handle list: inherit + standard streams
    all_handles = list(handles)
    for h in (stdin_h, stdout_h, stderr_h):
        if h is not None and h not in all_handles:
            all_handles.append(h)

    # Ensure all handles in the list are marked inheritable before creation.
    # We'll restore their original state afterwards.
    original_states = {}
    for h in all_handles:
        try:
            flags = get_handle_information(h)
            original_states[h] = bool(flags & HANDLE_FLAG_INHERIT)
            if not (flags & HANDLE_FLAG_INHERIT):
                set_handle_information(h, HANDLE_FLAG_INHERIT, HANDLE_FLAG_INHERIT)
        except OSError:
            # Handle might not support this; CreateProcess will fail later
            pass

    try:
        cmd_line = _build_command_line(command)
        pid, process_handle = create_process_with_handle_list(
            cmd_line,
            all_handles,
            stdin=stdin_h,
            stdout=stdout_h,
            stderr=stderr_h,
        )
    except OSError as exc:
        raise WSpawnError(str(exc), kind="os") from exc
    finally:
        # Restore original inheritable states
        for h, was_inheritable in original_states.items():
            try:
                target = HANDLE_FLAG_INHERIT if was_inheritable else 0
                set_handle_information(h, HANDLE_FLAG_INHERIT, target)
            except OSError:
                pass

    return SpawnedProcess(pid, process_handle, handles)

