def _open_nul_handle(access):
    """Open the NUL device and return its Windows HANDLE.

    *access* should be ``GENERIC_READ`` (0x80000000) or ``GENERIC_WRITE``
    (0x40000000).
    """
    import ctypes
    from ctypes import wintypes

    k32 = ctypes.windll.kernel32
    k32.CreateFileW.restype = wintypes.HANDLE
    k32.CreateFileW.argtypes = [
        wintypes.LPCWSTR,   # lpFileName
        wintypes.DWORD,     # dwDesiredAccess
        wintypes.DWORD,     # dwShareMode
        ctypes.c_void_p,    # lpSecurityAttributes
        wintypes.DWORD,     # dwCreationDisposition
        wintypes.DWORD,     # dwFlagsAndAttributes
        wintypes.HANDLE,    # hTemplateFile
    ]

    FILE_SHARE_READ = 0x00000001
    FILE_SHARE_WRITE = 0x00000002
    OPEN_EXISTING = 3

    h = k32.CreateFileW(
        "NUL",
        access,
        FILE_SHARE_READ | FILE_SHARE_WRITE,
        None,
        OPEN_EXISTING,
        0,
        None,
    )
    val = h.value if hasattr(h, 'value') else int(h)
    if val == -1 or val == 0xFFFFFFFF:
        raise WSpawnError("failed to open NUL device", kind="os")
    return val


